import { z } from "zod"

// Import generated schemas for FCMNode and FCMEdge
import FCMNodeSchema from './FCMNode.v1.zod';
import FCMEdgeSchema from './FCMEdge.v1.zod';

// Base schema from JSON Schema (generated by json-schema-to-zod)
// Note: The generated schema has inline node/edge definitions, but we use separate schemas
const BaseModelSchema = z.object({ 
  "id": z.number().int().describe("Unique model identifier").optional(), 
  "name": z.string().describe("Model name"), 
  "description": z.union([z.string().describe("Model description"), z.null().describe("Model description")]).describe("Model description").optional(), 
  "creatorLabel": z.union([z.string().describe("Creator label"), z.null().describe("Creator label")]).describe("Creator label").optional(),
  "problemStatement": z.union([z.string().describe("Problem statement"), z.null().describe("Problem statement")]).describe("Problem statement").optional(),
  "collectionType": z.union([z.string().describe("Collection type"), z.null().describe("Collection type")]).describe("Collection type").optional(),
  "projectId": z.number().int().describe("ID of the project this model belongs to"), 
  "nodes": z.array(FCMNodeSchema).describe("Array of FCM nodes").optional().default([]), 
  "edges": z.array(FCMEdgeSchema).describe("Array of FCM edges").optional().default([]), 
  "createdAt": z.string().datetime({ offset: true }).describe("Timestamp when model was created").optional(), 
  "updatedAt": z.union([z.string().datetime({ offset: true }).describe("Timestamp when model was last updated"), z.null().describe("Timestamp when model was last updated")]).describe("Timestamp when model was last updated").optional() 
}).describe("A Fuzzy Cognitive Map (FCM) model with nodes and edges");

// Enhanced schemas with proper date handling for API
export const ModelSchema = BaseModelSchema.extend({
  createdAt: z.string().or(z.date()).optional(),
  updatedAt: z.string().or(z.date()).nullable().optional(),
  nodes: z.array(FCMNodeSchema).optional(),
  edges: z.array(FCMEdgeSchema).optional(),
});

export const ModelStorageSchema = z.object({
  id: z.number(),
  projectId: z.number(),
  name: z.string(),
  description: z.string().nullable(),
  creatorLabel: z.string().nullable().optional(),
  problemStatement: z.string().nullable().optional(),
  collectionType: z.string().nullable().optional(),
  nodes: z.array(FCMNodeSchema),
  edges: z.array(FCMEdgeSchema),
  createdAt: z.date(),
  updatedAt: z.date().nullable()
});

export const CreateModelSchema = ModelSchema.omit({ id: true, createdAt: true, updatedAt: true });

export type Model = z.infer<typeof ModelSchema>;
export type ModelStorage = z.infer<typeof ModelStorageSchema>;

// Keep default export for codegen compatibility (will be overwritten on next codegen)
export default BaseModelSchema;
